<section class="gamification-list"><header><h1><?php echo $this->lang('Teams') ?></h1></header><div class="gamification-grid"><?php foreach ($teams as $team): ?><article class="gamification-card" style="--team-color:<?php echo utf8_htmlentities($team['color']) ?>"><h2><a href="<?php echo url('teams/'.$team['team_id'].'/'.$team['slug']) ?>"><?php echo utf8_htmlentities($team['title']) ?></a></h2><p><?php echo nl2br(utf8_htmlentities($team['description'])) ?></p><small><?php echo $this->lang('%d members', (int)$team['member_count']) ?></small></article><?php endforeach ?></div></section>
